tracking=''.join(x for x in scripts if 'googletagmanager.com/gtag/' in x or 'window.dataLayer' in x or 'function gtag_report_conversion' in x)
assert 'G-K5J958F2D4' in tracking and 'AW-17783643653' in tracking
STYLE=''.join('<link rel="stylesheet" href="'+f+'">' for f in ['assets/css/styles.css','assets/css/custom.css','assets/css/discovery.css','assets/css/news-content.css'])
def img(path,alt,lazy=False):
 im=Image.open(path)
 return f'<img src="{path}" width="{im.width}" height="{im.height}" alt="{html.escape(alt,quote=True)}" decoding="async" '+('loading="lazy"' if lazy else 'fetchpriority="high"')+'>'
def related(slugs):
 return '<section><h2>Thông tin liên quan</h2><div class="related">'+''.join(link(s,LH.parse(s+'.html').xpath('//h1')[0].text_content()) for s in slugs)+'</div></section>'
def render(data,area=False):
 slug=data['slug'];title=('Lái xe hộ '+data['name']+' tại Đà Nẵng') if area else data['title']
 parent='khu-vuc-phuc-vu' if area else 'tin-tuc';parent_name='Khu vực phục vụ' if area else 'Tin tức'
 imagepath=data['img'];caption='Ảnh minh họa tạo bằng AI; bối cảnh không đại diện một điểm đón cụ thể.' if data.get('key') else 'Ảnh minh họa chủ đề do Như Ý Driver cung cấp.'
 if area:
  sections=data['focus']+[
   chapter('Những yêu cầu có thể gửi cho Như Ý Driver',p('Bạn có thể gửi nhu cầu lái '+link('lai-xe-ho-o-to-da-nang','ô tô')+' hoặc '+link('lai-xe-ho-xe-may-da-nang','xe máy')+' của mình sau tiệc, lúc mệt hoặc khi cần người lái thay. Với lịch nhiều chặng, nói rõ thời lượng, điểm dừng và người bàn giao.','Nếu cần cả phương tiện đưa đón, hãy nêu rõ từ đầu; dịch vụ lái hộ ở đây dùng xe của khách. Thời gian đến và khả năng bố trí được trao đổi theo từng yêu cầu.')),
   chapter('Đặt chuyến và xác nhận giá',ul('Gửi địa chỉ hoặc ghim nơi xe đỗ cùng điểm trả.','Nêu loại xe, hộp số nếu là ô tô, số người đi cùng và giờ khởi hành.','Báo chặng ghé, thời gian chờ hoặc yêu cầu riêng.','Chờ xác nhận tài xế, giờ đón dự kiến và tổng phí trước khi bàn giao.')+p('Xem '+link('bang-gia-lai-xe-ho-da-nang','bảng giá ô tô và xe máy')+' để dự trù. Không có mức phụ phí riêng theo tên khu vực được tự đặt trong bài này. Giá thực tế và khoản chờ, đỗ xe, cầu đường nếu có được thống nhất trước chuyến.'))]
  rel=['bang-gia-lai-xe-ho-da-nang','huong-dan-dat-tai-xe-nhu-y-driver','can-chuan-bi-gi-khi-ban-giao-xe']
 else:sections=data['sections'];rel=data['related']+(['bang-gia-lai-xe-ho-da-nang'] if 'bang-gia-lai-xe-ho-da-nang' not in data['related'] else [])
 sections=sections+[chapter('Câu hỏi thường gặp',''.join('<details><summary>'+q+'</summary><p>'+ans+'</p></details>' for q,ans in data['faq']))]
 toc='<nav class="toc" aria-label="Mục lục"><strong>Trong trang này</strong><ul>'+''.join(f'<li><a href="#muc-{i}">{t}</a></li>' for i,(t,b) in enumerate(sections,1))+'</ul></nav>'
 content=''.join(f'<section><h2 id="muc-{i}">{t}</h2>{b}</section>' for i,(t,b) in enumerate(sections,1))
 tags='<nav class="topic-tags" aria-label="Chủ đề"><span>Chủ đề:</span>'+''.join(f'<a href="tin-tuc.html?chu-de={quote(t)}#noi-dung">#{t}</a>' for t in data['tags'])+'</nav>'
 breadcrumb={'@context':'https://schema.org','@type':'BreadcrumbList','itemListElement':[{'@type':'ListItem','position':1,'name':'Trang chủ','item':BASE},{'@type':'ListItem','position':2,'name':parent_name,'item':BASE+parent+'.html'},{'@type':'ListItem','position':3,'name':title,'item':BASE+slug+'.html'}]}
 schemas=[breadcrumb]
 if not area:schemas.append({'@context':'https://schema.org','@type':'Article','headline':title,'description':data['desc'],'inLanguage':'vi-VN','url':BASE+slug+'.html','mainEntityOfPage':{'@type':'WebPage','@id':BASE+slug+'.html'},'image':[BASE+imagepath],'author':{'@type':'Organization','name':'Như Ý Driver','url':BASE},'publisher':{'@type':'Organization','name':'Như Ý Driver','url':BASE}})
 jsonld=''.join('<script type="application/ld+json">'+json.dumps(s,ensure_ascii=False)+'</script>' for s in schemas)
 head=f'''<!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{html.escape(title)} | Như Ý Driver</title><meta name="description" content="{html.escape(data['desc'],quote=True)}"><link rel="canonical" href="{BASE+slug}.html"><meta property="og:title" content="{html.escape(title,quote=True)}"><meta property="og:description" content="{html.escape(data['desc'],quote=True)}"><meta property="og:image" content="{BASE+imagepath}"><meta property="og:url" content="{BASE+slug}.html"><meta property="og:type" content="{'website' if area else 'article'}"><meta property="og:locale" content="vi_VN"><link rel="icon" href="favicon.ico"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Manrope:wght@200..800&display=swap" rel="stylesheet">{STYLE}{jsonld}{tracking}<script src="assets/js/content.js" defer></script><script src="assets/js/news-navigation.js" defer></script></head>'''
 body=f'''<body><a class="skip" href="#main">Bỏ qua đến nội dung</a>{header}<main id="main" class="shell news-content"><nav class="breadcrumb" aria-label="Đường dẫn"><a href="index.html">Trang chủ</a> / <a href="{parent}.html">{parent_name}</a> / <span aria-current="page">{title}</span></nav><div class="hero"><div><p class="eyebrow">NHƯ Ý DRIVER · {'KHU VỰC PHỤC VỤ' if area else 'HƯỚNG DẪN LỊCH TRÌNH'}</p><h1>{title}</h1><p class="lead">{data['intro']}</p>{CTA}</div><figure>{img(imagepath,'Minh họa '+title.lower())}<figcaption>{caption}</figcaption></figure></div><div class="reading">{tags}{toc}{content}{related(rel)}<section class="contact"><h2>Trao đổi chuyến đi với Như Ý Driver</h2><p>Gửi điểm đón, điểm đến, loại xe và giờ đi để kiểm tra lịch. Chuyến được xác nhận sau khi hai bên thống nhất khả năng phục vụ, thời gian và chi phí.</p>{CTA}</section></div></main>{footer}</body></html>'''
 path=Path(slug+'.html')
 # All requested URLs were checked before this task; no pre-existing page is replaced.
 assert not path.exists(),f'Existing URL requires an in-place review: {path}'
 path.write_text(head+body,encoding='utf-8')
 data['title']=title

