# Expand the existing handover guide, rather than duplicating its search intent.
file=Path('can-chuan-bi-gi-khi-ban-giao-xe.html');s=file.read_text(encoding='utf-8')
responsibility='<section><h2 id="trach-nhiem-ban-giao">Nên hỏi gì về trách nhiệm trước khi bàn giao?</h2>'+p('Trước khi chốt, hãy hỏi đơn vị cung cấp về phạm vi công việc, người liên hệ khi có vấn đề và cách ghi nhận tình trạng xe. Nếu có điều khoản sử dụng, bảo hiểm hoặc cách xử lý sự cố, yêu cầu giải thích đúng với chuyến của bạn; không suy từ quảng cáo chung.','Bài hướng dẫn này không công bố một chính sách bảo hiểm hay bồi thường của Như Ý Driver. Những nội dung đó cần được hỏi và xác nhận trực tiếp trước khi nhận xe. Với xe thuê hoặc mượn, kiểm tra thêm sự đồng ý của chủ xe và các điều kiện liên quan.')+ul('Ai là đầu mối tiếp nhận thông tin khi phát sinh vấn đề?','Tình trạng xe, đồ dùng và chìa khóa được ghi nhận thế nào?','Các điều kiện nào đã được thống nhất và có thể lưu lại?','Nếu có thay đổi hành trình, ai có quyền xác nhận và cập nhật chi phí?')+p('Nếu phát hiện điểm cần làm rõ, dừng việc bàn giao ở vị trí phù hợp và liên hệ điều phối để thống nhất cách xử lý. Giữ lại nội dung trao đổi và thông tin chuyến để đối chiếu.')+'</section>'
s=s.replace('<section><h2>Đọc tiếp theo nhu cầu của bạn</h2>',responsibility+'<section><h2>Đọc tiếp theo nhu cầu của bạn</h2>',1)
s=s.replace('</ul></nav>','<li><a href="#trach-nhiem-ban-giao">Trách nhiệm trước khi bàn giao</a></li></ul></nav>',1)
file.write_text(s,encoding='utf-8')

