def card(data):
 return '<article class="card" data-search="'+html.escape(data['title']+' '+data['intro']+' '+' '.join(data['tags']),quote=True)+'" data-topics="'+html.escape('|'.join(data['tags']),quote=True)+'"><a class="card-image-link" href="'+data['slug']+'.html">'+img(data['img'],'Minh họa '+data['title'].lower(),True)+'</a><div><h3>'+link(data['slug'],data['title'])+'</h3><p>'+data['intro']+'</p>'+link(data['slug'],'Đọc nội dung →')+'</div></article>'
areas_section='<section id="khu-vuc"><h2>Lái xe hộ theo khu vực</h2><p>Chọn nơi có xe của bạn để xem cách gửi vị trí, chuẩn bị bàn giao và kiểm tra chuyến.</p><div class="cards">'+''.join(card(d) for d in AREAS)+'</div></section>'
s=s.replace('<section id="bai-viet">',areas_section+'<section id="bai-viet">',1)
pos=s.index('<section id="bai-viet">');end=s.index('</div></section>',pos)
s=s[:end]+''.join(card(d) for d in ARTICLES)+s[end:]
topics=['Hải Châu','Sơn Trà','Cẩm Lệ – Hòa Xuân','Thanh Khê','Ngũ Hành Sơn','Liên Chiểu','Lịch trình','Hội An','Huế','Đối tác','Sự kiện']
buttons=''.join(f'<button type="button" data-topic="{t}" aria-pressed="false">#{t}</button>' for t in topics)
s=s.replace('</div><p id="search-status"',buttons+'</div><p id="search-status"',1)
s=s.replace('19 nội dung','29 nội dung')
s=s.replace('<a href="#bai-viet">Bài viết &amp; hướng dẫn</a>','<a href="#khu-vuc">Theo khu vực</a><a href="#bai-viet">Bài viết &amp; hướng dẫn</a>',1)
file.write_text(s,encoding='utf-8')
file=Path('assets/js/content.js');s=file.read_text(encoding='utf-8').replace("['dich-vu', 'bai-viet']","['dich-vu', 'khu-vuc', 'bai-viet']")
s=s.replace("if (section) section.hidden = ![...section.querySelectorAll('.card')].some(card => !card.hidden);", "if (section) {\n        section.hidden = ![...section.querySelectorAll('.card')].some(card => !card.hidden);\n        const categoryLink = document.querySelector('.news-search a[href=\"#' + id + '\"]');\n        if (categoryLink) categoryLink.hidden = section.hidden;\n      }")
file.write_text(s,encoding='utf-8')
file=Path('assets/css/news-content.css');s=file.read_text(encoding='utf-8')
s+='\n.news-content [id]{scroll-margin-top:108px}.news-content figcaption{font-size:12px;line-height:1.6;color:#536171;margin-top:10px}.news-content .uniform-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}.news-content .uniform-grid img{width:100%;height:auto;border-radius:8px}.news-content .uniform-grid figure{margin:0}.news-content .related{grid-template-columns:repeat(auto-fit,minmax(min(100%,240px),1fr))}@media(max-width:700px){.news-content .uniform-grid{grid-template-columns:1fr}.news-content .uniform-grid img{max-width:420px;margin:auto}}\n'
file.write_text(s,encoding='utf-8')

# Sitemap contains only complete pages; retain existing URL order and lastmod values.
file=Path('sitemap.xml');tree=ET.parse(file);ns='{http://www.sitemaps.org/schemas/sitemap/0.9}';root=tree.getroot();seen={e.text for e in root.findall(ns+'url/'+ns+'loc')}
for data in AREAS+ARTICLES:
 url=BASE+data['slug']+'.html'
 if url not in seen:
  node=ET.SubElement(root,ns+'url');ET.SubElement(node,ns+'loc').text=url;seen.add(url)
ET.register_namespace('',ns[1:-1]);tree.write(file,encoding='utf-8',xml_declaration=True)
Path('work/new-content-manifest.json').write_text(json.dumps({'areas':AREAS,'articles':ARTICLES},ensure_ascii=False,indent=2),encoding='utf-8')
print('Created 6 regional pages and 4 guides; expanded handover guide; hub has 29 clickable cards.')
